{
  "research_question": {
    "text": "Investigating the performance of Tabular Foundation Models (TFMs) for molecular property prediction, compared to classical prediction methods.",
    "passage_ids": ["Pd1c7f35cd2f11aafddb1", "P4825a7abcff05959794f"]
  },
  "methodology": {
    "text": "TFMs paired with frozen molecular foundation model embeddings and 2D descriptor sets, enabling in-context learning. Performance is evaluated across two benchmark suites.",
    "passage_ids": ["Pff4aa2871e9ff198b4d8", "P4825a7abcff05959794f"]
  },
  "quantitative_findings": {
    "text": "XGBoost delivers fast predictions but has weaker overall performance compared to TabPFN with RDKit2d and Mordred descriptors. The fine-tuned CheMeleon baseline has a larger average relative RMSE gap and is slower. The TFM-based approach outperforms classical prediction methods across the benchmarks.",
    "passage_ids": ["P108e928d108f6dfcaa06", "Pd1c7f35cd2f11aafddb1", "P4825a7abcff05959794f"]
  },
  "validation": {
    "text": "Statistical significance is determined using Tukey’s honest significant difference (HSD) test and Nemenyi post hoc comparison following Friedman’s test.",
    "passage_ids": ["Pb9fca254bcba839b9486"]
  },
  "limitations": {
    "text": "The work focuses on single-molecule prediction tasks and higher-dimensional representations start to approach practical limits. Extensions to chemically more complex settings remain open and potentially challenging.",
    "passage_ids": ["P643fa7e99e67e19bc39d"]
  },
  "relevance": {
    "text": "The results suggest that in-context learning with TFMs provides a promising approach for molecular property prediction, reducing computational cost and outperforming classical methods.",
    "passage_ids": ["Pd1c7f35cd2f11aafddb1", "P4825a7abcff05959794f"]
  }
}

{
  "research_question": {
    "text": "Develop a physics-informed active learning framework for formulation discovery with limited data.",
    "passage_ids": ["P81a59cacbec18d9d799d"]
  },
  "methodology": {
    "text": "KolTa framework uses a three-stage physics-informed predictor, greedy rule, and calibration of ensemble disagreement and the target-temperature physics residual for active learning.",
    "passage_ids": ["P7a7baba911ac98745f26", "P3aab088091a8e861fcc6"]
  },
  "quantitative_findings": {
    "text": "KolTa outperforms seven of eight comparator strategies in mean area under the learning curve (AULC) on every task, winning 75 of 78 paired comparisons.",
    "passage_ids": ["P81a59cacbec18d9d799d", "P3aab088091a8e861fcc6"]
  },
  "validation": {
    "text": "Validation is performed using one-sided exact sign and Wilcoxon signed-rank tests, yielding p < 0.05.",
    "passage_ids": ["Pe7e9c11fe9084c405ac8"]
  },
  "limitations": {
    "text": "The current physics loss applies soft constraints at five fixed temperatures per task, and extrapolation beyond the training temperature range has not been evaluated.",
    "passage_ids": ["P4846c85bf29e78e64243"]
  },
  "relevance": {
    "text": "The research could potentially improve formulation discovery by incorporating physical relations into the temperature-response function and extending the model to jointly varying temperature and pressure.",
    "passage_ids": ["P4846c85bf29e78e64243"]
  }
}

{
  "research_question": {
    "text": "Can a condition-aware diffusion language model (CAGenMol) improve the success rate, binding affinity, and drug-likeness in molecular generation compared to existing methods?",
    "passage_ids": ["P44042743953f16e3d84f"]
  },
  "methodology": {
    "text": "CAGenMol is a generative framework that decouples constraint perception from molecular reasoning, using a Unified Constraint Adaptor and a Condition-Aware Diffusion Backbone. It is trained using a two-stage strategy: supervised fine-tuning followed by Step-PPO maximization. The training focuses on QED and SA as affinity improves.",
    "passage_ids": ["Pc8b5cb51b2d37e72e9b0", "P8fed53317669f0e9b7a4"]
  },
  "quantitative_findings": {
    "text": "CAGenMol establishes a new state-of-the-art with a 69.7% success rate, surpassing the best baseline by over 16%. It achieves superior balance in QED, SA, and maintains strong affinity while retaining the highest diversity. It also produces molecules with superior docking scores and the highest proportion of Ames-negative candidates.",
    "passage_ids": ["P76ca90e79a14507db6e5", "P491f26cdfdb642139c2e"]
  },
  "validation": {
    "text": "Experiments were conducted on structure-conditioned, property-conditioned, and dual-conditioned benchmarks. Additional experiments were done on an additional benchmark following Zheng et al. (2024) to demonstrate robustness.",
    "passage_ids": ["P44042743953f16e3d84f", "Pa6ad3e747717150c8318"]
  },
  "limitations": {
    "text": "Limited computational resources prevented large-scale training and extensive benchmarking. The reliance on predictions from tools and models may impact overall performance.",
    "passage_ids": ["Pa6ad3e747717150c8318", "Pc8b5cb51b2d37e72e9b0"]
  },
  "relevance": {
    "text": "The results highlight the effectiveness of CAGenMol for realistic drug design scenarios, balancing binding optimization and toxicity avoidance within a unified framework.",
    "passage_ids": ["P491f26cdfdb642139c2e"]
  }
}

{
  "research_question": {
    "text": "How do Tabular Foundation Models (TabPFN) compare with other methods in terms of computational cost and predictive performance for molecular property prediction tasks?",
    "passage_ids": ["P32b1dcc174a184ec87e4", "P56735e28ff3b6bbba744", "P108e928d108f6dfcaa06"]
  },
  "methodology": {
    "text": "The study uses Tabular Foundation Models (TabPFN) with various descriptor sets, including RDKit2d and Mordred descriptors, and compares them with XGBoost and a fine-tuned CheMeleon baseline. The performance is evaluated using Tukey’s honest significant difference (HSD) test with α = 0.05 on five seed-specific benchmark scores.",
    "passage_ids": ["Pb9fca254bcba839b9486", "P32b1dcc174a184ec87e4", "P108e928d108f6dfcaa06"]
  },
  "quantitative_findings": {
    "text": "TabPFN combined with RDKit2d descriptors and, especially, Mordred descriptors achieves the strongest overall performance, while XGBoost delivers very fast predictions. The fine-tuned CheMeleon baseline has an average relative RMSE gap that is about 10 percentage points larger while also being an order of magnitude slower. Across the combined benchmark suite, TabPFN-CheMeleonFP achieves 50 wins out of 58 tasks, corresponding to an 86.2% win rate and an average rank of 4.52.",
    "passage_ids": ["P32b1dcc174a184ec87e4", "P108e928d108f6dfcaa06", "P56735e28ff3b6bbba744"]
  },
  "validation": {
    "text": "The validation is performed using Tukey’s honest significant difference (HSD) test with α = 0.05 on the five seed-specific benchmark scores, which quantifies variation due to model stochasticity rather than uncertainty over alternative molecular test sets.",
    "passage_ids": ["Pb9fca254bcba839b9486"]
  },
  "limitations": {
    "text": "The limitations include the practical limits of higher-dimensional representations and the focus on single-molecule prediction tasks. Extensions to chemically more complex settings, such as many-component mixtures, remain open and potentially challenging.",
    "passage_ids": ["Pc173451e942f2c6ab84c"]
  },
  "relevance": {
    "text": "The research has implications for the development of efficient and accurate methods for molecular property prediction, which is crucial for drug discovery and design, materials science, and other fields.",
    "passage_ids": []
  }
}

